import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  sonnerCloseClassName,
  sonnerDescriptionClassName,
  sonnerTitleClassName,
  sonnerToastClassName,
  sonnerViewportClassName,
} from "./view";

export {
  sonnerActionClassName,
  sonnerCloseClassName,
  sonnerDescriptionClassName,
  sonnerTitleClassName,
  sonnerToastClassName,
  sonnerViewportClassName,
} from "./view";

export type ToastConfig<ParentMessage> = Readonly<{
  title: string;
  description?: string | undefined;
  action?: Html | undefined;
  onClose?: ParentMessage | undefined;
  className?: string | undefined;
}>;

export type ViewportConfig = Readonly<{
  children: readonly Html[];
  className?: string | undefined;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const viewportView = <ParentMessage>({
  children,
  className,
}: ViewportConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("aria-live", "polite"),
      h.Attribute("aria-atomic", "true"),
      h.DataAttribute("slot", "sonner-viewport"),
      h.Class(classNames(sonnerViewportClassName, className)),
    ],
    children
  );
};

export const toastView = <ParentMessage>({
  title,
  description,
  action,
  onClose,
  className,
}: ToastConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "status"),
      h.DataAttribute("slot", "sonner-toast"),
      h.Class(classNames(`${sonnerToastClassName} relative`, className)),
    ],
    [
      h.div(
        [
          h.DataAttribute("slot", "sonner-title"),
          h.Class(sonnerTitleClassName),
        ],
        [title]
      ),
      description === undefined
        ? h.empty
        : h.div(
            [
              h.DataAttribute("slot", "sonner-description"),
              h.Class(sonnerDescriptionClassName),
            ],
            [description]
          ),
      action === undefined ? h.empty : action,
      onClose === undefined
        ? h.empty
        : h.button(
            [
              h.Type("button"),
              h.AriaLabel("Dismiss toast"),
              h.OnClick(onClose),
              h.DataAttribute("slot", "sonner-close"),
              h.Class(sonnerCloseClassName),
            ],
            ["x"]
          ),
    ]
  );
};

export const sonnerViewportClassName =
  "fixed bottom-4 right-4 z-50 flex w-full max-w-sm flex-col gap-2";
export const sonnerToastClassName =
  "rounded-lg border border-gray-200 bg-white p-4 text-sm shadow-lg";
export const sonnerTitleClassName = "font-semibold text-gray-950";
export const sonnerDescriptionClassName = "mt-1 text-gray-600";
export const sonnerActionClassName =
  "mt-3 rounded-md bg-gray-950 px-3 py-1.5 text-xs font-medium text-white";
export const sonnerCloseClassName =
  "absolute right-2 top-2 rounded-sm p-1 text-gray-500 hover:text-gray-950 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Sonner from "./index";

const view = (show: boolean): Html =>
  Sonner.viewportView<string>({
    children: show
      ? [
          Sonner.toastView<string>({
            title: "Event has been created",
            description: "Sunday, December 03, 2023 at 9:00 AM",
            onClose: "close",
          }),
        ]
      : [],
  });

describe("Sonner registry view", () => {
  test("renders an aria-live toast stack", () => {
    Scene.scene(
      {
        update: (model: boolean): readonly [boolean, []] => [model, []],
        view,
      },
      Scene.with(true),
      Scene.expect(Scene.text("Event has been created")).toExist(),
      Scene.expect(Scene.role("status")).toExist(),
      Scene.expect(Scene.role("button", { name: "Dismiss toast" })).toExist()
    );
  });
});
